// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Agents read projects over MCP"
// Changes: The tool registry of the agent interface: a tool is a name, an agent-facing description, a zod argument
//          shape and a run function returning plain JSON. Tool groups (read tools now, draft tools later) are lists of
//          tools; registerTools puts them on an MCP server and turns ToolErrors into MCP tool errors.

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { CallToolResult, ToolAnnotations } from '@modelcontextprotocol/sdk/types.js'
import { z } from 'zod'
import type { ProjectStore } from '../projects.server'

/** What every tool runs against. */
export interface AgentContext {
  store: ProjectStore
}

/** An error the agent caused (unknown id, unusable argument, forbidden write); its message is shown to the agent. */
export class ToolError extends Error {
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Agents create, edit and discard drafts"
  // Changes: Optional details (e.g. the current text of a part after a refused stale edit); with details the error
  //          text is JSON {error, ...details}.
  constructor(
    message: string,
    readonly details?: Record<string, unknown>,
  ) {
    super(message)
  }
}

export interface AgentTool<Shape extends z.ZodRawShape = z.ZodRawShape> {
  name: string
  description: string
  input: Shape
  /** Read tools are read-only and idempotent; draft-writing tools say otherwise. */
  annotations: ToolAnnotations
  run(args: z.infer<z.ZodObject<Shape>>, ctx: AgentContext): unknown
}

export const READ_ONLY: ToolAnnotations = { readOnlyHint: true, idempotentHint: true, openWorldHint: false }

/** Typed tool definition (infers the argument type from the shape). */
export const defineTool = <Shape extends z.ZodRawShape>(tool: AgentTool<Shape>): AgentTool => tool as unknown as AgentTool

const textResult = (text: string, isError = false): CallToolResult => ({ content: [{ type: 'text', text }], ...(isError && { isError }) })

export function registerTools(server: McpServer, tools: readonly AgentTool[], ctx: AgentContext) {
  for (const tool of tools) {
    server.registerTool(
      tool.name,
      { description: tool.description, inputSchema: tool.input, annotations: tool.annotations },
      async (args: unknown) => {
        try {
          return textResult(JSON.stringify(await tool.run(args as never, ctx), null, 2))
        } catch (err) {
          if (err instanceof ToolError) {
            return textResult(err.details ? JSON.stringify({ error: err.message, ...err.details }, null, 2) : err.message, true)
          }
          throw err
        }
      },
    )
  }
}
